// ---- prove 版本 1 JSON 的严格读取 -----------------------------------------
//
// 只实现 prove 已公开的格式所需的 JSON 子集：对象、数组、字符串、整数。
// 不接受小数、指数、null/true/false 作为字段值；空白与字段次序按 JSON
// 规则自由；重复字段、未知字段与对象之后的多余内容一律判错。解析器只
// 扫描传入文本，不做任何文件或内存映射 I/O。

// JSON 记号类型。null/true/false 在本格式里没有合法位置，识别出来只是为
// 了给出“类型不符”的明确错误，而不是误报成语法损坏。
enum class JsonTok { error, object_begin, object_end, array_begin, array_end,
                     string, number, colon, comma, literal };

struct JsonParser {
    std::string_view text;
    std::size_t pos = 0;
    std::string error;

    bool ws() {
        while (pos < text.size()) {
            const char c = text[pos];
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                ++pos;
            } else {
                break;
            }
        }
        return true;
    }

    bool eof() const { return pos >= text.size(); }

    char peek() const { return text[pos]; }

    bool fail(std::string msg) {
        // 每个调用点只会在尚未出错时进入；保留第一条原因。
        if (error.empty()) {
            error = std::move(msg);
        }
        return false;
    }

    // 读取一个 JSON 字符串字面量（text[pos] 必须是 '"'），把解码后的
    // UTF-8 内容写入 out。prove 的摘要/字段名/side 都只含 ASCII，这里仍
    // 按 JSON 规则处理转义与 uXXXX（含代理对），以便对任意输入给出确定
    // 结果而非越界读取。
    bool read_string(std::string& out) {
        out.clear();
        ++pos;  // 跳过起始引号
        while (true) {
            if (eof()) {
                return fail("unterminated JSON string");
            }
            const char c = text[pos++];
            if (static_cast<unsigned char>(c) < 0x20) {
                return fail("unescaped control character in JSON string");
            }
            if (c == '"') {
                return true;
            }
            if (c == '\\') {
                if (eof()) {
                    return fail("unterminated escape in JSON string");
                }
                const char e = text[pos++];
                switch (e) {
                    case '"': out.push_back('"'); break;
                    case '\\': out.push_back('\\'); break;
                    case '/': out.push_back('/'); break;
                    case 'b': out.push_back('\b'); break;
                    case 'f': out.push_back('\f'); break;
                    case 'n': out.push_back('\n'); break;
                    case 'r': out.push_back('\r'); break;
                    case 't': out.push_back('\t'); break;
                    case 'u': {
                        std::uint32_t cp = 0;
                        if (!read_hex4(cp)) {
                            return fail("invalid \\u escape in JSON string");
                        }
                        // UTF-16 代理对：\uD800-\uDBFF 后必须紧跟
                        // \uDC00-\uDFFF。
                        if (cp >= 0xD800 && cp <= 0xDBFF) {
                            if (pos + 1 < text.size() && text[pos] == '\\' &&
                                text[pos + 1] == 'u') {
                                pos += 2;
                                std::uint32_t lo = 0;
                                if (!read_hex4(lo) || lo < 0xDC00 ||
                                    lo > 0xDFFF) {
                                    return fail("invalid UTF-16 surrogate pair "
                                                "in JSON string");
                                }
                                cp = 0x10000 + ((cp - 0xD800) << 10) +
                                     (lo - 0xDC00);
                            } else {
                                return fail("lone UTF-16 high surrogate in JSON "
                                            "string");
                            }
                        } else if (cp >= 0xDC00 && cp <= 0xDFFF) {
                            return fail("lone UTF-16 low surrogate in JSON "
                                        "string");
                        }
                        append_utf8(cp, out);
                        break;
                    }
                    default:
                        return fail("invalid escape sequence in JSON string");
                }
            } else {
                out.push_back(c);
            }
        }
    }

    // 从 text[pos..pos+4) 读取四个十六进制位；不足或非法返回 false。
    bool read_hex4(std::uint32_t& out) {
        if (pos + 4 > text.size()) {
            return false;
        }
        std::uint32_t v = 0;
        for (int i = 0; i < 4; ++i) {
            const char c = text[pos++];
            v <<= 4;
            if (c >= '0' && c <= '9') {
                v |= static_cast<std::uint32_t>(c - '0');
            } else if (c >= 'a' && c <= 'f') {
                v |= static_cast<std::uint32_t>(c - 'a' + 10);
            } else if (c >= 'A' && c <= 'F') {
                v |= static_cast<std::uint32_t>(c - 'A' + 10);
            } else {
                return false;
            }
        }
        out = v;
        return true;
    }

    static void append_utf8(std::uint32_t cp, std::string& out) {
        if (cp <= 0x7F) {
            out.push_back(static_cast<char>(cp));
        } else if (cp <= 0x7FF) {
            out.push_back(static_cast<char>(0xC0 | (cp >> 6)));
            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
        } else if (cp <= 0xFFFF) {
            out.push_back(static_cast<char>(0xE0 | (cp >> 12)));
            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
        } else {
            out.push_back(static_cast<char>(0xF0 | (cp >> 18)));
            out.push_back(static_cast<char>(0x80 | ((cp >> 12) & 0x3F)));
            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
        }
    }

    // 跳过一个 JSON 值（对象/数组/字符串/数字/literal）。仅在需要跳过
    // 未知值时使用；类型检查由调用方按字段要求做。
    bool skip_value() {
        ws();
        if (eof()) {
            return fail("expected a JSON value");
        }
        const char c = peek();
        if (c == '{') return skip_container(true);
        if (c == '[') return skip_container(false);
        if (c == '"') {
            std::string s;
            return read_string(s);
        }
        if (c == '-' || (c >= '0' && c <= '9')) {
            return scan_number_raw(nullptr, /*must_be_uint=*/false);
        }
        return scan_literal();
    }

    bool skip_container(bool is_object) {
        const char open = is_object ? '{' : '[';
        const char close = is_object ? '}' : ']';
        if (peek() != open) {
            return fail("expected container");
        }
        ++pos;
        ws();
        if (!eof() && peek() == close) {
            ++pos;
            return true;
        }
        while (true) {
            ws();
            if (is_object) {
                if (eof() || peek() != '"') {
                    return fail("expected string key in JSON object");
                }
                std::string key;
                if (!read_string(key)) {
                    return false;
                }
                ws();
                if (eof() || peek() != ':') {
                    return fail("expected ':' after JSON object key");
                }
                ++pos;
            }
            if (!skip_value()) {
                return false;
            }
            ws();
            if (eof()) {
                return fail("unterminated JSON container");
            }
            const char sep = peek();
            if (sep == close) {
                ++pos;
                return true;
            }
            if (sep != ',') {
                return fail("expected ',' or container end in JSON");
            }
            ++pos;
        }
    }

    bool scan_literal() {
        if (text.compare(pos, 4, "true") == 0) {
            pos += 4;
            return true;
        }
        if (text.compare(pos, 5, "false") == 0) {
            pos += 5;
            return true;
        }
        if (text.compare(pos, 4, "null") == 0) {
            pos += 4;
            return true;
        }
        return fail("invalid JSON literal");
    }

    // 扫描一个 JSON 数字的原始字符区间（不跨越空白/逗号/括号）。
    // must_be_uint 为真时额外要求它是 leaf_count/leaf_index 可接受的
    // 无符号整数：无符号、无小数、无指数，且值在 0..2^64-1。
    // raw 非空时写入 [start,pos) 的原文（version 不必用）。
    bool scan_number_raw(std::string* raw, bool must_be_uint) {
        const std::size_t start = pos;
        if (!eof() && peek() == '-') {
            ++pos;
            if (must_be_uint) {
                return fail("negative integer is not allowed");
            }
        }
        // 整数部分：JSON 不允许前导 0（"0" 之后不能再跟数字）。
        if (eof() || peek() < '0' || peek() > '9') {
            return fail("invalid JSON number");
        }
        if (peek() == '0') {
            ++pos;
            if (!eof() && peek() >= '0' && peek() <= '9') {
                return fail("leading zeros are not allowed in JSON numbers");
            }
        } else {
            while (!eof() && peek() >= '0' && peek() <= '9') {
                ++pos;
            }
        }
        bool fraction_or_exponent = false;
        if (!eof() && peek() == '.') {
            fraction_or_exponent = true;
            ++pos;
            if (eof() || peek() < '0' || peek() > '9') {
                return fail("invalid JSON fraction");
            }
            while (!eof() && peek() >= '0' && peek() <= '9') {
                ++pos;
            }
        }
        if (!eof() && (peek() == 'e' || peek() == 'E')) {
            fraction_or_exponent = true;
            ++pos;
            if (!eof() && (peek() == '+' || peek() == '-')) {
                ++pos;
            }
            if (eof() || peek() < '0' || peek() > '9') {
                return fail("invalid JSON exponent");
            }
            while (!eof() && peek() >= '0' && peek() <= '9') {
                ++pos;
            }
        }
        if (must_be_uint && fraction_or_exponent) {
            // 1.0、1e0 这类写法在 JSON 里是数字，但不是“JSON 整数”，
            // leaf_count/leaf_index/version 必须准确保留整数值。
            return fail("only JSON integers are accepted for this field");
        }
        if (raw != nullptr) {
            raw->assign(text.data() + start, pos - start);
        }
        return true;
    }

    // 读取字段值位置上的无符号 64 位 JSON 整数。
    bool read_uint64(std::uint64_t& out, std::string_view field) {
        ws();
        if (eof()) {
            return fail(std::string("missing value for field \"") +
                        std::string(field) + "\"");
        }
        const char c = peek();
        if (c == '"') {
            return fail(std::string("field \"") + std::string(field) +
                        "\" must be a JSON integer, got a string");
        }
        if (c == 't' || c == 'f' || c == 'n') {
            return fail(std::string("field \"") + std::string(field) +
                        "\" must be a JSON integer, got a boolean or null");
        }
        if (c == '{' || c == '[') {
            return fail(std::string("field \"") + std::string(field) +
                        "\" must be a JSON integer, got a container");
        }
        if (c != '-' && (c < '0' || c > '9')) {
            return fail(std::string("field \"") + std::string(field) +
                        "\" has an invalid value");
        }
        const std::size_t start = pos;
        if (!scan_number_raw(nullptr, /*must_be_uint=*/true)) {
            return false;
        }
        const std::string_view digits(text.data() + start, pos - start);
        const auto res = std::from_chars(
            digits.data(), digits.data() + digits.size(), out);
        if (res.ec != std::errc{} ||
            res.ptr != digits.data() + digits.size()) {
            return fail(std::string("field \"") + std::string(field) +
                        "\" integer is out of unsigned 64-bit range");
        }
        return true;
    }

    // 读取字段值位置上的 JSON 字符串。
    bool read_string_value(std::string& out, std::string_view field) {
        ws();
        if (eof()) {
            return fail(std::string("missing value for field \"") +
                        std::string(field) + "\"");
        }
        const char c = peek();
        if (c != '"') {
            return fail(std::string("field \"") + std::string(field) +
                        "\" must be a JSON string");
        }
        return read_string(out);
    }
};

// 把恰好 64 个小写十六进制字符还原为 32 字节摘要。长度不符、含非十六
// 进制字符或使用大写字符都明确失败：不截断、不替换损坏内容。
bool parse_digest_hex(const std::string& hex, Digest& out,
                      std::string_view field) {
    if (hex.size() != 64) {
        return false;
    }
    for (std::size_t i = 0; i < 32; ++i) {
        unsigned int hi = 0;
        unsigned int lo = 0;
        for (unsigned int* nibble :
             {static_cast<unsigned int*>(nullptr)}) {
            (void)nibble;
        }
        auto nib = [](char c, unsigned int& v) -> bool {
            if (c >= '0' && c <= '9') {
                v = static_cast<unsigned int>(c - '0');
                return true;
            }
            // 只接受小写：A-F 等大写字符在此失败，而不是被当作同一摘要。
            if (c >= 'a' && c <= 'f') {
                v = static_cast<unsigned int>(c - 'a' + 10);
                return true;
            }
            return false;
        };
        if (!nib(hex[2 * i], hi) || !nib(hex[2 * i + 1], lo)) {
