// 把恰好 64 个小写十六进制字符还原为 32 字节摘要。长度不符、含非十六
// 进制字符或使用大写字符都明确失败：不截断、不替换损坏内容。
bool parse_digest_hex(const std::string& hex, Digest& out,
                      std::string_view field) {
    if (hex.size() != 64) {
        return false;
    }
    for (std::size_t i = 0; i < 32; ++i) {
        unsigned int hi = 0;
        unsigned int lo = 0;
        for (unsigned int* nibble :
             {static_cast<unsigned int*>(nullptr)}) {
            (void)nibble;
        }
        auto nib = [](char c, unsigned int& v) -> bool {
            if (c >= '0' && c <= '9') {
                v = static_cast<unsigned int>(c - '0');
                return true;
            }
            // 只接受小写：A-F 等大写字符在此失败，而不是被当作同一摘要。
            if (c >= 'a' && c <= 'f') {
                v = static_cast<unsigned int>(c - 'a' + 10);
                return true;
            }
            return false;
        };
        if (!nib(hex[2 * i], hi) || !nib(hex[2 * i + 1], lo)) {
            return false;
        }
        out[i] = static_cast<std::uint8_t>((hi << 4) | lo);
    }
    (void)field;
    return true;
}

}  // namespace

