// 跳过一个 JSON 值（对象/数组/字符串/数字/literal）。仅在需要跳过
// 未知值时使用；类型检查由调用方按字段要求做。
bool skip_value() {
    ws();
    if (eof()) {
        return fail("expected a JSON value");
    }
    const char c = peek();
    if (c == '{') return skip_container(true);
    if (c == '[') return skip_container(false);
    if (c == '"') {
        std::string s;
        return read_string(s);
    }
    if (c == '-' || (c >= '0' && c <= '9')) {
        return scan_number_raw(nullptr, /*must_be_uint=*/false);
    }
    return scan_literal();
}

bool skip_container(bool is_object) {
    const char open = is_object ? '{' : '[';
    const char close = is_object ? '}' : ']';
    if (peek() != open) {
        return fail("expected container");
    }
    ++pos;
    ws();
    if (!eof() && peek() == close) {
        ++pos;
        return true;
    }
    while (true) {
        ws();
        if (is_object) {
            if (eof() || peek() != '"') {
                return fail("expected string key in JSON object");
            }
            std::string key;
            if (!read_string(key)) {
                return false;
            }
            ws();
            if (eof() || peek() != ':') {
                return fail("expected ':' after JSON object key");
            }
            ++pos;
        }
        if (!skip_value()) {
            return false;
        }
        ws();
        if (eof()) {
            return fail("unterminated JSON container");
        }
        const char sep = peek();
        if (sep == close) {
            ++pos;
            return true;
        }
        if (sep != ',') {
            return fail("expected ',' or container end in JSON");
        }
        ++pos;
    }
}

bool scan_literal() {
    if (text.compare(pos, 4, "true") == 0) {
        pos += 4;
        return true;
    }
    if (text.compare(pos, 5, "false") == 0) {
        pos += 5;
        return true;
    }
    if (text.compare(pos, 4, "null") == 0) {
        pos += 4;
        return true;
    }
    return fail("invalid JSON literal");
}

