    if (!p.error.empty()) {
        result.error = "proof text rejected: ";
        // 个别底层信息已自带语境；统一加前缀以便调用方直接展示。
        if (p.error.rfind("proof text rejected: ", 0) == 0 ||
            p.error.rfind("unsupported proof version", 0) == 0) {
            result.error = p.error;
        } else {
            result.error += p.error;
        }
        return result;
    }

    result.proof = std::move(proof);
    return result;
}

