            if (!p.read_uint64(proof.leaf_count, "leaf_count")) {
                break;
            }
        } else if (bit == kLeafIndex) {
            if (!p.read_uint64(proof.leaf_index, "leaf_index")) {
                break;
            }
        } else if (bit == kLeaf) {
            if (!read_digest_value(p, proof.leaf, "leaf")) {
                break;
            }
