#include <iostream>
#include <iterator>
#include <sstream>
#include <string>
#include <vector>
#include "merkle.h"
using namespace branchaudit;
static Digest unhex(const std::string& h) {
    Digest d{};
    for (size_t i=0;i<32;i++){
        auto n=[](char c){return c<='9'?c-'0':c-'a'+10;};
        d[i]=(unsigned char)((n(h[2*i])<<4)|n(h[2*i+1]));
    }
    return d;
}
int main(int argc, char** argv){
    std::stringstream ss; ss << std::cin.rdbuf();
    std::string text = ss.str();
    // 证明读取不打印：截获输出
    std::stringstream co, ce; auto* oo=std::cout.rdbuf(co.rdbuf()); auto* oe=std::cerr.rdbuf(ce.rdbuf());
    auto r = merkle_proof_from_json(text);
    std::cout.rdbuf(oo); std::cerr.rdbuf(oe);
    if(!r.ok()){ std::cout<<"PARSE FAIL: "<<r.error<<"\n"; return 2; }
    const auto& p=r.proof;
    std::cout<<"parsed count="<<p.leaf_count<<" index="<<p.leaf_index
             <<" siblings="<<p.siblings.size()<<" root="<<to_hex(p.root)
             <<" leaf="<<to_hex(p.leaf)<<"\n";
    std::cout<<"library stdout/stderr bytes: "<<co.str().size()<<","<<ce.str().size()<<"\n";
    if(argc>=3){
        Digest trusted=unhex(argv[1]);
        Digest leaf=unhex(argv[2]);
        auto v=merkle_verify_proof(p, trusted, leaf);
        std::cout<<"verify(good): "<<(v.ok()?"PASS":"FAIL")<<"\n";
        // 坏叶子：全 00
        Digest bad{};
        auto v2=merkle_verify_proof(p, trusted, bad);
        std::cout<<"verify(bad leaf): "<<(v2.ok()?"PASS":"FAIL")<<" - "<<v2.error<<"\n";
        // 用 proof.root 以外的可信根
        Digest wrong=trusted; wrong[0]^=1;
        auto v3=merkle_verify_proof(p, wrong, leaf);
        std::cout<<"verify(wrong root): "<<(v3.ok()?"PASS":"FAIL")<<"\n";
    }
    return 0;
}
