                "\"siblings\":[{\"side\":\"right\",\"digest\":\"" +
                hex_of(labc) + "\"}]";
            const auto at = t.find(from);
            t.replace(at, from.size(), "\"siblings\":{}");
            expect_parse_fail(t, "siblings as object");
