#include <iostream>
#include <sstream>
#include <string>
#include "merkle.h"
using namespace branchaudit;
int main(){
    std::stringstream ss; ss << std::cin.rdbuf();
    std::string all = ss.str();
    // 记录以 \x1e 分隔
    std::size_t start=0, accepted=0, rejected=0;
    while(start < all.size()){
        std::size_t end = all.find('\x1e', start);
        std::string text = all.substr(start, end==std::string::npos?std::string::npos:end-start);
        if(end==std::string::npos) end=all.size();
        start=end+1;
        if(text.empty()) continue;
        auto r=merkle_proof_from_json(text);
        if(r.ok()){
            ++accepted;
            const auto&p=r.proof;
            std::cout<<"OK "<<p.leaf_count<<" "<<p.leaf_index<<" "<<p.siblings.size()<<"\n";
        } else {
            ++rejected;
            std::cout<<"ERR "<<r.error<<"\n";
        }
    }
    std::cerr<<"accepted="<<accepted<<" rejected="<<rejected<<"\n";
}
