import json, random, subprocess, sys
random.seed(42)
H = "0123456789abcdef"
def dg(seed):
    rnd=random.Random(seed)
    return ''.join(rnd.choice(H) for _ in range(64))
WS=[' ','\t','\n','\r','  ','\t \n','\r\n\t']
def ws():
    return random.choice(WS) if random.random()<0.8 else ''
def render(obj, indent_level=0):
    # custom JSON renderer with random whitespace around tokens, field order shuffled
    if isinstance(obj, dict):
        items=list(obj.items())
        random.shuffle(items)
        parts=[]
        for k,v in items:
            parts.append(json.dumps(k)+ws()+':'+ws()+render(v))
        return '{'+ws()+ (ws()+','+ws()).join(parts)+ws()+'}'
    if isinstance(obj, list):
        return '['+ws()+(ws()+','+ws()).join(render(x) for x in obj)+ws()+']'
    return json.dumps(obj)

cases=[]
for i in range(4000):
    n=random.choice([1,2,3,5,7,8])
    idx=random.randrange(n)
    sibs=[]
    pos=idx; level=n
    while level>1:
        if pos%2==0:
            if pos+1<level:
                sibs.append({"side":"right","digest":dg(1000+i*7+len(sibs))})
        else:
            sibs.append({"side":"left","digest":dg(2000+i*7+len(sibs))})
        pos//=2; level=level-level//2
    obj={"version":1,"root":dg(i),"leaf_count":n,"leaf_index":idx,"leaf":dg(i+500000),"siblings":sibs}
    text=render(obj)
    if random.random()<0.5:
        text=ws()+text+ws()+('\n' if random.random()<0.7 else '')
    # self-check: it must be valid JSON
    json.loads(text)
    cases.append(text)
data='\x1e'.join(cases)+'\x1e'
p=subprocess.run(['/tmp/fuzz_harness'],input=data,capture_output=True,text=True)
lines=p.stdout.splitlines()
errs=[l for l in lines if l.startswith('ERR')]
print(p.stderr.strip())
print("unexpected rejections:",len(errs))
for e in errs[:5]: print(e)
# verify counts match python values for a sample
pys=[]
for c in cases:
    o=json.loads(c)
    pys.append((o['leaf_count'],o['leaf_index'],len(o['siblings'])))
oks=[tuple(map(int,l.split(' ')[1:])) for l in lines if l.startswith('OK')]
mismatch=[(a,b) for a,b in zip(pys,oks) if a!=b]
print("value mismatches:",len(mismatch), mismatch[:3])
sys.exit(1 if errs or mismatch else 0)
EOF
